6: export function useFocusTrap<T extends HTMLElement>(
7:   isActive: boolean,
8:   onEscape?: () => void,
9: ): RefObject<T | null> {
10:   const containerRef = useRef<T | null>(null);
11:   const previousFocusRef = useRef<HTMLElement | null>(null);
12: 
13:   useEffect(() => {
14:     if (!isActive) {
15:       return undefined;
16:     }
17: 
18:     previousFocusRef.current =
19:       document.activeElement instanceof HTMLElement
20:         ? document.activeElement
21:         : null;
22: 
23:     const container = containerRef.current;
24:     if (container) {
25:       const focusable = Array.from(
26:         container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
27:       );
28:       if (focusable.length > 0) {
29:         focusable[0].focus();
30:       } else {
31:         container.focus();
32:       }
33:     }
34: 
35:     const handleKeyDown = (event: KeyboardEvent) => {
36:       if (event.key === "Escape") {
37:         event.stopPropagation();
38:         onEscape?.();
39:         return;
40:       }
41: 
42:       if (event.key !== "Tab" || !containerRef.current) {
43:         return;
44:       }
45: 
46:       const focusableElements = Array.from(
47:         containerRef.current.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
48:       );
49:       if (focusableElements.length === 0) {
50:         return;
51:       }
52: 
53:       const first = focusableElements[0];
54:       const last = focusableElements[focusableElements.length - 1];
55:       const active = document.activeElement;
56: 
57:       if (event.shiftKey) {
58:         if (active === first || !containerRef.current.contains(active)) {
59:           event.preventDefault();
60:           last.focus();
61:         }
62:       } else if (active === last || !containerRef.current.contains(active)) {
63:         event.preventDefault();
64:         first.focus();
65:       }
66:     };
67: 
68:     document.addEventListener("keydown", handleKeyDown);
69:     return () => {
70:       document.removeEventListener("keydown", handleKeyDown);
71:       if (
72:         previousFocusRef.current &&
73:         typeof previousFocusRef.current.focus === "function"
74:       ) {
75:         previousFocusRef.current.focus();
76:       }
77:     };
78:   }, [isActive, onEscape]);
79: 
80:   return containerRef;
